  orderDate: "2026-03-01",
  deliveryDate: "2026-03-01",
  currency: { id: 5 }, // EUR
  orderLines: [{
    description: "FX Agio Test Service",
    count: 1,
    unitPriceExcludingVatCurrency: 13892,
    vatType: { id: vat25?.id },
  }]
});
